import React, { useState, useEffect } from 'react';
import Typewriter from 'typewriter-effect';
import { Link } from 'react-scroll';
import Social from './Miscellaneous/Social';
import ThemeToggle from './ThemeToggle';
import styles from './LeftPanel.module.css';

const LeftPanel: React.FC = () => {
  const [isMobile, setIsMobile] = useState(false);
  const [activeSection, setActiveSection] = useState('about');
  
  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth <= 768);
    };
    
    checkMobile();
    window.addEventListener('resize', checkMobile);
    
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  // Track active section on scroll in mobile
  useEffect(() => {
    if (!isMobile) return;

    const handleScroll = () => {
      const sections = ['about', 'resume', 'contact'];
      const offset = 250; // Offset for header

      // Find which section we're currently in
      for (let i = sections.length - 1; i >= 0; i--) {
        const sectionId = sections[i];
        const element = document.getElementById(sectionId);
        if (element) {
          const rect = element.getBoundingClientRect();
          // If the section is above the offset line, it's active
          if (rect.top <= offset) {
            setActiveSection(sectionId);
            return;
          }
        }
      }
      // If no section found, default to first
      setActiveSection('about');
    };

    window.addEventListener('scroll', handleScroll);
    handleScroll(); // Check initial position

    return () => window.removeEventListener('scroll', handleScroll);
  }, [isMobile]);

  const handleMobileClick = (sectionId: string) => {
    const element = document.getElementById(sectionId);
    if (element) {
      const yOffset = -200; // Offset for sticky header
      const y = element.getBoundingClientRect().top + window.pageYOffset + yOffset;
      window.scrollTo({ top: y, behavior: 'smooth' });
    }
  };

  const navItems = [
    { id: 'about', label: 'About' },
    { id: 'resume', label: 'Resume' },
    { id: 'contact', label: 'Contact' },
  ];

  return (
    <div className={styles.leftPanelContainer}>
      <div className={styles.header}>
        <ThemeToggle />
        <br />
        <h1>Trent Currie</h1>
        <div className={styles.typewriterWrapper}>
          <Typewriter
            options={{
              strings: [
                'Software Engineer',
                'D&D Dungeon Master',
                'Wine Enthusiast',
                'Planeswalker',
                'Yogi',
                'L33T Gamer'
              ],
              autoStart: true,
              loop: true,
            }}
          />
        </div>
      </div>

      <nav className={styles.navContainer}>
        {navItems.map((item) => (
          isMobile ? (
            <button
              key={item.id}
              onClick={() => handleMobileClick(item.id)}
              className={`${styles.navButton} ${activeSection === item.id ? styles.active : ''}`}
            >
              <div className={styles.squareIcon} />
              <span className={styles.navLabel}>{item.label}</span>
            </button>
          ) : (
            <Link
              key={item.id}
              to={item.id}
              spy={true}
              smooth={true}
              duration={500}
              containerId="right-panel-scroll"
              className={styles.navButton}
              activeClass={styles.active}
              offset={0}
              isDynamic={true}
            >
              <div className={styles.squareIcon} />
              <span className={styles.navLabel}>{item.label}</span>
            </Link>
          )
        ))}
      </nav>

      <div className={styles.footer}>
        <Social />
      </div>
    </div>
  );
};

export default LeftPanel;
